+package ai.unifiedprocess.petclinic.vet.ui;
+
+import ai.unifiedprocess.petclinic.core.ui.MainLayout;
+import ai.unifiedprocess.petclinic.vet.domain.Specialty;
+import ai.unifiedprocess.petclinic.vet.domain.Vet;
+import ai.unifiedprocess.petclinic.vet.domain.VetRepository;
+import com.vaadin.flow.component.UI;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H2;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.data.provider.DataProvider;
+import com.vaadin.flow.router.NavigationTrigger;
+import com.vaadin.flow.router.PageTitle;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.theme.lumo.LumoUtility;
+import org.springframework.dao.DataAccessException;
+
+import java.util.stream.Collectors;
+import java.util.stream.Stream;
+
+/** UC-002: Browse veterinarians and their specialties using infinite scrolling. */
+@Route(value = "vets", layout = MainLayout.class)
+@PageTitle("Veterinarians")
+public class VeterinariansView extends VerticalLayout {
+
+    private final transient VetRepository repository;
+
+    public VeterinariansView(VetRepository repository) {
+        this.repository = repository;
+        setSizeFull();
+
+        H2 heading = new H2("Veterinarians");
+        heading.addClassNames(LumoUtility.Margin.NONE);
+
+        Grid<Vet> grid = new Grid<>();
+        grid.setAriaLabel("Veterinarians");
+        grid.setSelectionMode(Grid.SelectionMode.NONE);
+        grid.addColumn(Vet::firstName).setHeader("First Name").setKey("firstName");
+        grid.addColumn(Vet::lastName).setHeader("Last Name").setKey("lastName");
+        grid.addColumn(vet -> vet.specialties().isEmpty() ? "none"
+                        : vet.specialties().stream().map(Specialty::name).collect(Collectors.joining(", ")))
+                .setHeader("Specialties").setKey("specialties").setFlexGrow(2);
+        grid.setSizeFull();
+        grid.setDataProvider(DataProvider.fromCallbacks(
+                query -> fetchPage(query.getOffset(), query.getLimit()),
+                query -> countVets()));
+
+        add(heading, grid);
+        expand(grid);
+    }
+
+    private Stream<Vet> fetchPage(int offset, int limit) {
+        try {
+            return repository.findPage(offset, limit);
+        } catch (DataAccessException exception) {
+            showError(exception);
+            return Stream.empty();
+        }
+    }
+
+    private int countVets() {
+        try {
+            return repository.count();
+        } catch (DataAccessException exception) {
+            showError(exception);
+            return 0;
+        }
+    }
+
+    private void showError(DataAccessException exception) {
+        // Grid callbacks also run after navigation, when scrolling requests a page.
+        UI ui = UI.getCurrent();
+        ui.getInternals().getRouter().handleExceptionNavigation(ui,
+                ui.getInternals().getActiveViewLocation(), exception,
+                NavigationTrigger.PROGRAMMATIC, null);
+    }
+}
