+package ai.unifiedprocess.petclinic.vet.ui;
+
+import ai.unifiedprocess.petclinic.PetClinicTestBase;
+import ai.unifiedprocess.petclinic.UseCase;
+import ai.unifiedprocess.petclinic.core.ui.ApplicationErrorView;
+import ai.unifiedprocess.petclinic.vet.domain.Vet;
+import ai.unifiedprocess.petclinic.vet.domain.VetRepository;
+import ai.unifiedprocess.petclinic.welcome.ui.WelcomeView;
+import com.vaadin.flow.component.UI;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.Paragraph;
+import com.vaadin.flow.component.sidenav.SideNav;
+import com.vaadin.flow.data.provider.Query;
+import org.jooq.DSLContext;
+import org.junit.jupiter.api.Test;
+import org.springframework.beans.factory.annotation.Autowired;
+import org.springframework.dao.DataAccessResourceFailureException;
+import org.springframework.test.context.bean.override.mockito.MockitoSpyBean;
+
+import java.util.List;
+
+import static ai.unifiedprocess.demo.petclinic.database.Tables.VETS;
+import static ai.unifiedprocess.demo.petclinic.database.Tables.VET_SPECIALTIES;
+import static org.junit.jupiter.api.Assertions.*;
+import static org.mockito.Mockito.*;
+
+class UC002ViewVeterinariansTest extends PetClinicTestBase {
+
+    @Autowired
+    private DSLContext dsl;
+
+    @MockitoSpyBean
+    private VetRepository repository;
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = {"BR-002", "BR-003"})
+    void anonymousVisitorOpensDirectoryFromNavigationAndReadsSpecialties() {
+        navigate(WelcomeView.class);
+        SideNav menu = assertDoesNotThrow(() -> find(SideNav.class).single(), "Expected main menu");
+        test(menu).clickItem("Veterinarians");
+
+        assertEquals("vets", UI.getCurrent().getInternals().getActiveViewLocation().getPath());
+        Grid<Vet> grid = grid();
+        var tester = test(grid);
+        assertEquals(6, tester.size());
+        assertEquals(List.of("First Name", "Last Name", "Specialties"),
+                List.of(tester.getHeaderCell(0), tester.getHeaderCell(1), tester.getHeaderCell(2)));
+        assertEquals(List.of("James", "Carter", "none"),
+                List.of(tester.getCellText(0, 0), tester.getCellText(0, 1), tester.getCellText(0, 2)));
+        assertEquals(List.of("Linda", "Douglas", "dentistry, surgery"),
+                List.of(tester.getCellText(1, 0), tester.getCellText(1, 1), tester.getCellText(1, 2)));
+        assertEquals(List.of("Helen", "Leary", "radiology"),
+                List.of(tester.getCellText(3, 0), tester.getCellText(3, 1), tester.getCellText(3, 2)));
+        assertEquals("none", tester.getCellText(2, 2));
+        assertEquals("surgery", tester.getCellText(4, 2));
+        assertEquals("radiology", tester.getCellText(5, 2));
+        assertEquals(6, repository.count(), "Browsing must leave reference data unchanged");
+    }
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-001")
+    void gridFetchesBoundedPagesWithNoGapsOrDuplicateRows() {
+        for (int index = 0; index < 125; index++) {
+            dsl.insertInto(VETS, VETS.FIRST_NAME, VETS.LAST_NAME)
+                    .values("Veterinarian", "Vet%03d".formatted(index)).execute();
+        }
+        navigate(VeterinariansView.class);
+        Grid<Vet> grid = grid();
+        assertFalse(grid.getDataProvider().isInMemory());
+        assertFalse(grid.isAllRowsVisible());
+        assertEquals(131, grid.getDataProvider().size(new Query<>()));
+        clearInvocations(repository);
+
+        var first = grid.getDataProvider().fetch(new Query<>(0, 50, List.of(), null, null)).toList();
+        var second = grid.getDataProvider().fetch(new Query<>(50, 50, List.of(), null, null)).toList();
+        var last = grid.getDataProvider().fetch(new Query<>(100, 50, List.of(), null, null)).toList();
+        assertEquals(50, first.size());
+        assertEquals(50, second.size());
+        assertEquals(31, last.size());
+        var loaded = java.util.stream.Stream.of(first, second, last).flatMap(List::stream).toList();
+        assertEquals(131, loaded.stream().map(Vet::id).distinct().count());
+        assertEquals(repository.findPage(0, 131).toList(), loaded);
+        assertTrue(grid.getDataProvider().fetch(new Query<>(131, 50, List.of(), null, null)).findAny().isEmpty());
+        verify(repository).findPage(0, 50);
+        verify(repository).findPage(50, 50);
+        verify(repository).findPage(100, 50);
+    }
+
+    @Test
+    @UseCase(id = "UC-002", scenario = "A1: No Veterinarians Registered")
+    void emptyDirectoryRendersGridWithNoRows() {
+        dsl.deleteFrom(VET_SPECIALTIES).execute();
+        dsl.deleteFrom(VETS).execute();
+        navigate(VeterinariansView.class);
+
+        assertEquals(0, test(grid()).size());
+    }
+
+    @Test
+    @UseCase(id = "UC-002")
+    void countFailureShowsApplicationErrorAndRemovesGrid() {
+        navigate(VeterinariansView.class);
+        Grid<Vet> grid = grid();
+        doThrow(new DataAccessResourceFailureException("Veterinarians unavailable"))
+                .when(repository).count();
+
+        grid.getDataProvider().size(new Query<>());
+
+        assertErrorView();
+    }
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-001")
+    void laterPageFailureShowsApplicationErrorAndRemovesLoadedRows() {
+        navigate(VeterinariansView.class);
+        Grid<Vet> grid = grid();
+        assertEquals(6, test(grid).size());
+        doThrow(new DataAccessResourceFailureException("Veterinarians unavailable"))
+                .when(repository).findPage(2, 2);
+
+        grid.getDataProvider().fetch(new Query<>(2, 2, List.of(), null, null)).toList();
+
+        assertErrorView();
+    }
+
+    private void assertErrorView() {
+        assertDoesNotThrow(() -> find(ApplicationErrorView.class).single(), "Expected application error view");
+        assertDoesNotThrow(() -> find(Paragraph.class).withText("Veterinarians unavailable").single(),
+                "Expected readable failure message");
+        assertTrue(find(Grid.class).all().isEmpty(), "No vet list may remain after a data-access failure");
+    }
+
+    @SuppressWarnings("unchecked")
+    private Grid<Vet> grid() {
+        return assertDoesNotThrow(() -> find(Grid.class).single(), "Expected veterinarians grid");
+    }
+}
